    ) AS seed(role_key, role_label, file_name, storage_path, file_size_bytes, page_count, field_manifest)
  LOOP
    INSERT INTO public.labor_interview_templates (
      location_id,
      role_key,
      role_label,
      description
    )
    VALUES (
      v_location_id,
      v_row.role_key,
      v_row.role_label,
      'Adair Forsythe interview template seeded from verified fillable PDFs.'
    )
    ON CONFLICT (location_id, role_key) DO UPDATE
    SET
      role_label = EXCLUDED.role_label,
      updated_at = now()
    RETURNING id INTO v_template_id;

    SELECT id, version_no
      INTO v_version_id, v_version_no
    FROM public.labor_interview_template_versions
    WHERE template_id = v_template_id
      AND version_no = 1
    LIMIT 1;

    IF v_version_id IS NULL THEN
      INSERT INTO public.labor_interview_template_versions (
        template_id,
        version_no,
        status,
        is_current,
        pdf_verification_status,
        metadata,
        changelog
      )
      VALUES (
        v_template_id,
        1,
        'draft',
        false,
        'missing_pdf',
        '{}'::jsonb,
        'Seeded from verified fillable interview PDF.'
      )
      RETURNING id, version_no INTO v_version_id, v_version_no;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.labor_interview_template_versions
      WHERE id = v_version_id
        AND status = 'published'
        AND pdf_verification_status = 'verified_fields'
        AND jsonb_array_length(pdf_field_manifest) > 0
    ) THEN
      CONTINUE;
    END IF;

    v_published_at := now();

    SELECT COALESCE(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'seed_source', 'business-logic/interviews/pdf-field-verification',
        'verified_at', v_published_at,
        'verified_by', 'codex-production-seed',
        'field_count', jsonb_array_length(v_row.field_manifest),
        'storage_seeded', true
      )
      INTO v_metadata
    FROM public.labor_interview_template_versions
    WHERE id = v_version_id;

    UPDATE public.labor_interview_template_versions
    SET
      source_pdf_bucket = 'labor-interview-documents',
      source_pdf_path = v_row.storage_path,
      source_pdf_file_name = v_row.file_name,
      source_pdf_mime_type = 'application/pdf',
      source_pdf_file_size_bytes = v_row.file_size_bytes,
      pdf_page_count = v_row.page_count,
      pdf_field_manifest = v_row.field_manifest,
      pdf_verification_status = 'verified_fields',
      changelog = 'Published verified fillable PDF template for production interviews.',
      metadata = v_metadata
    WHERE id = v_version_id;

    SELECT jsonb_build_object(
      'template', jsonb_build_object(
        'id', t.id,
        'location_id', t.location_id,
        'role_key', t.role_key,
        'role_label', t.role_label,
        'description', t.description
      ),
      'version', jsonb_build_object(
        'id', tv.id,
        'version_no', tv.version_no,
        'status', 'published',
        'pdf_verification_status', 'verified_fields',
        'source_pdf_bucket', 'labor-interview-documents',
        'source_pdf_path', v_row.storage_path,
        'source_pdf_file_name', v_row.file_name,
        'pdf_page_count', v_row.page_count,
        'pdf_field_manifest', v_row.field_manifest,
        'metadata', v_metadata,
        'published_at', v_published_at
      ),
      'questions', COALESCE((
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', q.id,
            'question_key', q.question_key,
            'category', q.category,
            'prompt', q.prompt,
            'helper_text', q.helper_text,
            'sequence_order', q.sequence_order,
            'required', q.required,
            'answer_format', q.answer_format,
            'mapped_pdf_field_name', q.mapped_pdf_field_name,
            'metadata', COALESCE(q.metadata, '{}'::jsonb)
          )
          ORDER BY q.sequence_order
        )
        FROM public.labor_interview_template_questions q
        WHERE q.template_version_id = tv.id
      ), '[]'::jsonb)
    )
    INTO v_snapshot
    FROM public.labor_interview_template_versions tv
    JOIN public.labor_interview_templates t ON t.id = tv.template_id
    WHERE tv.id = v_version_id;

    UPDATE public.labor_interview_template_versions
    SET is_current = false
    WHERE template_id = v_template_id;

    UPDATE public.labor_interview_template_versions
    SET
      status = 'published',
      is_current = true,
      published_at = v_published_at,
      published_snapshot = v_snapshot
    WHERE id = v_version_id;
  END LOOP;
END;
$$;
